qa=[dict(kind='interpretive-name-scope',locators=['jinshu:053:c0009','jinshu:053:s0070','jinshu:053:s0072'],sourceQuotes=['南風起兮吹白沙','沙門，太子小字也。'],finding='白沙 occurs in an omen verse. Its application to this prince through the sand/Shamen wordplay is an inferred literary reference, matching the stored strongly-inferred certainty; the text explicitly attests 沙門, not 白沙, as the childhood name. This assessment does not upgrade 白沙 to an explicitly attested nickname and does not rely on it to merge or separate any person.',scopeEffect='All14separations independently supported by name/family/career context; no source/alias edit proposed.'),dict(kind='outside-English-name-mistranslation',locators=['jinshu:031:s0282','jinshu:031:c0376','jinshu:031:m0592'],sourceQuote='會稽王昱',finding='The current idiomatic Yu Yi and literal Prince Hui of Kuaiji Yu garble the explicit Kuaiji Prince 昱. The Chinese owner remains clear; do not interpret that English as an identifying alternative name.'),dict(kind='outside-mourning-frame/date-label-defect',locators=['jinshu:020:s0095','jinshu:020:c0826'],sourceQuote='寧康二年七月，簡文帝崩再周而遇閏。',finding='The Chinese says a second mourning anniversary after Jianwen’s death meets an intercalary month. Current English says he died at that point and saved attestation labels Xianan2 rather than this Ningkang frame. Do not use that English or inherited conversion as a newly approved death date; no numerical repair inferred.'),dict(kind='outside-polity-and-cause-unqualified',locators=['weishu:001:p169 identityHints.polityHints','weishu:001:c0799'],sourceQuotes=['立叡子昱','司馬昱死，子昌明僭立'],finding='The Weishu annal’s Tuoba Dai reign frame does not make the named Jin ruler a Dai servant; 死 does not specify natural death. Existing polity hint and natural-cause metadata are not certified by this identity assessment.'),dict(kind='outside-English-redundant-title',locators=['zizhitongjian:097:s0243'],sourceQuote='會稽王昱',finding='Both English fields say Prince Kuaiji of Kuaiji instead of rendering 昱. Chinese identification is unambiguous; no invented name or homonym uncertainty.'),dict(kind='outside-English-unsupported-survival-word',locators=['jinshu:037:s0396','jinshu:037:c2058 value.kinshipTerm.en'],sourceQuotes=['四子：虞、矯、紹、確','是日，虞及矯、紹...又為豐餘黨所害'],finding='Four sons survived adds survival not stated by the list, and the next frame kills Yu/Jiao/Shao. Preserve the family identity evidence without certifying that English survival assertion.'),dict(kind='outside-English-collective-substitution',locators=['jinshu:101:s0185'],sourceQuote='四戰，瑜皆敗',finding='Idiomatic says Jin fled where Chinese specifically reports 瑜’s defeat in all four battles. Chinese identity and command frame govern; no chronology/fact repair supplied.')]
